    }
  ],
  "scenes": [
    {
      "sceneId": "L01",
      "characters": [
        "P03",
        "P04",
        "P02",
        "P05"
      ],
      "flow": [
        {
          "action": "门内传出歌声。"
        },
        {
          "speaker": "P03",
          "line": "“不知是天神或凡女，快去询问。”",
          "mode": "spoken"
        },
        {
          "action": "狼和狮子摇尾站在道边。"
        },
        {
          "speaker": "P03",
          "line": "“野兽摇尾，我们仍畏惧。”",
          "mode": "spoken"
        },
        {
          "action": "波利特斯和同伴甲向门内呼唤。"
        },
        {
          "action": "基尔克打开闪光大门。"
        },
        {
          "speaker": "P04",
          "line": "“请进，客人。”",
          "mode": "spoken"
        },
        {
          "speaker": "P02",
          "line": "“我担心有欺诈，留在门外。”",
          "mode": "spoken"
        },
        {
          "action": "波利特斯和同伴甲随基尔克入内。"
        },
        {
          "action": "欧律洛科斯留在门外。"
        }
      ]
    },
    {
      "sceneId": "L02",
      "characters": [
        "P04",
        "P03",
        "P05"
      ],
      "flow": [
        {
          "action": "基尔克为波利特斯和同伴甲倒饮料。"
        },
        {
          "action": "波利特斯和同伴甲饮下饮料。"
        },
        {
          "action": "基尔克用魔杖打他们。"
        },
        {
          "action": "波利特斯和同伴甲变出猪头猪声。"
        },
        {
          "action": "猪头的人不断流泪。"
        },
        {
          "action": "他们被赶进猪栏。"
        },
        {
          "action": "基尔克扔下橡实。"
        }
      ]
    },
    {
      "sceneId": "L03",
      "characters": [
        "P01",
        "P02"
      ],
      "flow": [
        {
          "action": "欧律洛科斯跑回快船。"
        },
        {
          "action": "欧律洛科斯流泪。"
        },
        {
          "speaker": "P01",
          "line": "“同伴们遭遇了什么？”",
          "mode": "spoken"
        },
        {
          "speaker": "P02",
          "line": "“我们按吩咐去了橡林。”",
          "mode": "spoken"
        },
        {
          "speaker": "P02",
          "line": "“山间有华丽宅邸，歌声洪亮。”",
          "mode": "spoken"
        },
        {
          "speaker": "P02",
          "line": "“她开门邀请，他们随她进去。”",
          "mode": "spoken"
        },
        {
          "speaker": "P02",
          "line": "“我留在门外，再没人出来。”",
          "mode": "spoken"
        },
        {
          "action": "欧律洛科斯抱住奥德修斯的膝头。"
        },
        {
          "speaker": "P02",
          "line": "“请不要逼我前去，留在这里吧。”",
          "mode": "spoken"
        },
        {
          "speaker": "P02",
          "line": "“我知道你自己回不来。”",
          "mode": "spoken"
        },
        {
          "speaker": "P02",
          "line": "“你也带不回同伴。”",
          "mode": "spoken"
        },
        {
          "speaker": "P02",
          "line": "“让我们和船上的同伴逃跑吧。”",
          "mode": "spoken"
        },
        {
          "action": "奥德修斯把镶银钉的佩剑背到肩上。"
        },
        {
          "action": "奥德修斯拿起弯弓。"
        },
        {
          "speaker": "P01",
          "line": "“欧律洛科斯，你就留在这里吧。”",
          "mode": "spoken"
        },
        {
          "speaker": "P01",
          "line": "“在乌黑的船旁吃喝。”",
          "mode": "spoken"
        },
        {
          "speaker": "P01",
          "line": "“我却得前去，责任在肩。”",
          "mode": "spoken"
        }
      ]
    }
  ]
}

